/** Public entry point — the only module consumers/docs should import from. */
export { useDataGridPinnedRows, type UseDataGridPinnedRowsOptions, type UseDataGridPinnedRowsResult } from "./use-data-grid-pinned-rows";
export { DataGridPinnedRow, type DataGridPinnedRowProps } from "./pinned-row";
export { DataGridPinnedRowBand, type DataGridPinnedRowBandProps } from "./pinned-row-band";
export {
  useDataGridAggregate,
  DataGridAggregateReporter,
  type AggregateReducer,
  type AggregateSpecs,
  type UseDataGridAggregateOptions,
  type DataGridAggregateReporterProps,
} from "./use-data-grid-aggregate";
export {
  useDataGridServerAggregate,
  DataGridServerAggregateReporter,
  PENDING_SERVER_AGGREGATE,
  type FetchAggregatesRequest,
  type ServerAggregateResult,
  type ServerAggregateStatus,
  type UseDataGridServerAggregateOptions,
  type DataGridServerAggregateReporterProps,
} from "./use-data-grid-server-aggregate";

"use client";

import { useMemo } from "react";
import type { DataGridPlugin, RowBandRenderCtx } from "@/registry/default/components/data-grid/data-grid";
import { DataGridPinnedRowBand } from "./pinned-row-band";
import type { ServerAggregateStatus } from "./use-data-grid-server-aggregate";

/** Options for {@link useDataGridPinnedRows}. */
export type UseDataGridPinnedRowsOptions = {
  /** Rows pinned in a sticky band directly under the header (e.g. a computed totals row) — a SEPARATE array from `data`, not indices into it. Omit (or pass `[]`) for no top band. */
  topRows?: readonly unknown[];
  /** Rows pinned in a sticky band at the viewport's bottom edge; see {@link UseDataGridPinnedRowsOptions.topRows}. */
  bottomRows?: readonly unknown[];
  /** Marks both bands while server values load, go stale, or fail: the bands dim and set `data-status`, and set `aria-busy` only while values load or go stale. Default `"ready"`. */
  status?: ServerAggregateStatus;
};

/** Return value of {@link useDataGridPinnedRows}. */
export type UseDataGridPinnedRowsResult = {
  /** Pass this into the grid's `plugins` prop (`plugins={[pinnedRows.plugin]}`) — stable identity across renders as long as `topRows`/`bottomRows` keep the same array references and `status` stays the same. */
  plugin: DataGridPlugin<unknown>;
};

const EMPTY_ROWS: readonly never[] = [];

/**
 * Pinned top/bottom row bands, as a single hook. Row bands affect layout height and `aria-rowcount`,
 * so the grid resolves the band row counts synchronously at first render (root.tsx keeps all of
 * that arithmetic and calls this plugin's `rowBands.render` per band segment). Cells render via the
 * same `DataGridCell`/cell-type pipeline as data rows (same columns, alignment, formatting) but are
 * readOnly by default unless a column's own `readOnly` says otherwise, and aren't keyboard-navigable
 * in v1 (documented).
 */
export function useDataGridPinnedRows(options: UseDataGridPinnedRowsOptions = {}): UseDataGridPinnedRowsResult {
  const { topRows = EMPTY_ROWS, bottomRows = EMPTY_ROWS, status = "ready" } = options;
  // Stable identity keyed on the two row arrays' own references; a `plugins` array that churns this
  // member every render re-resolves the grid's plugins for no reason.
  const plugin = useMemo<DataGridPlugin<unknown>>(
    () => ({
      name: "pinned-rows",
      rowBands: {
        top: topRows,
        bottom: bottomRows,
        render: (ctx: RowBandRenderCtx) => renderPinnedRowBand(ctx, status),
      },
    }),
    [topRows, bottomRows, status],
  );

  return { plugin };
}

function renderPinnedRowBand(ctx: RowBandRenderCtx, status: ServerAggregateStatus) {
  const { position, rows, renderedColumns, layout, rowHeight, template, headerHeight, ariaRowIndexBase } = ctx;
  return (
    <DataGridPinnedRowBand
      position={position}
      rows={rows}
      renderedColumns={renderedColumns}
      layout={layout}
      rowHeight={rowHeight}
      template={template}
      headerHeight={headerHeight}
      ariaRowIndexBase={ariaRowIndexBase}
      status={status}
    />
  );
}

"use client";

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";
import { DataGridCell } from "@/registry/default/components/data-grid/data-grid";
import type { GridColumnLayout, RenderedColumn } from "@/registry/default/components/data-grid/data-grid-sdk";
import { useDataGridSelector, type DataGridStoreState } from "@/registry/default/components/data-grid/data-grid-sdk";

export type DataGridPinnedRowProps = {
  /** The band this row belongs to; part of the fallback row id. */
  position: "top" | "bottom";
  /** The consumer-supplied pinned row object (from `useDataGridPinnedRows`'s `topRows`/`bottomRows` options — never a member of `data`). */
  row: unknown;
  /** Position within its own band, 0-based — the `data-grid-pinned-row-index` marker and the `getRowId` index argument of the row's resolved id; never `ViewCoord`/`aria-colindex` (pinned rows aren't in the data index space). */
  bandIndex: number;
  renderedColumns: readonly RenderedColumn[];
  layout: GridColumnLayout;
  gridRowStart: number;
  /** Root's aria index layout: header rows, pinned-top next, then data rows, pinned-bottom last. */
  ariaRowIndex: number;
  className?: string;
};

function resolvePinnedRowId(getRowId: DataGridStoreState["getRowId"], row: unknown, bandIndex: number, position: "top" | "bottom"): string {
  let id: unknown;
  try {
    id = getRowId(row, bandIndex);
  } catch {
    id = undefined;
  }
  return typeof id === "string" && id !== "" ? id : `__pinned-${position}-${bandIndex}`;
}

/**
 * A pinned top/bottom band row: reuses
  * `DataGridCell` in its `pinnedRow` mode for identical cell-type rendering/alignment/column tracks as
 * data rows, but bypasses `DataGridRow`'s `useDataGridRow(viewRowIndex)` store lookup entirely —
 * pinned rows are a separate array the consumer supplies to `useDataGridPinnedRows`, not indices
 * into `data`/`viewIndex`, so they never sort, filter, or participate in range selection or the
 * rows-channel (documented v1 scope). Not memoized like `DataGridRow`: pinned bands are always
 * fully rendered (never virtualized — a handful of totals/frozen rows, not tens of
 * thousands), so there's no window-shift-driven re-render pressure to protect against.
 */
export function DataGridPinnedRow(props: DataGridPinnedRowProps): ReactNode {
  const { position, row, bandIndex, renderedColumns, layout, gridRowStart, ariaRowIndex, className } = props;
  const getRowId = useDataGridSelector((s) => s.getRowId);
  // Pinned rows such as aggregates often carry no id, so a throwing or empty getRowId falls back to a band id.
  const rowId = resolvePinnedRowId(getRowId, row, bandIndex, position);
  const markerColOffset = layout.markerWidth > 0 ? 2 : 1;
  return (
    <div
      role="row"
      aria-rowindex={ariaRowIndex}
      data-grid-pinned-row-index={bandIndex}
      className={cn("group/row", className)}
      style={{
        display: "grid",
        gridTemplateColumns: "subgrid",
        gridColumn: "1 / -1",
        gridRowStart,
      }}
    >
      {renderedColumns.map(({ column, index }) => (
        <DataGridCell
          key={column.id}
          row={row}
          rowId={rowId}
          viewRowIndex={bandIndex}
          column={column}
          viewColumnIndex={index}
          gridColOffset={markerColOffset}
          pinnedRow
        />
      ))}
    </div>
  );
}

"use client";

import type { CSSProperties, ReactNode } from "react";
import { GRID_LAYER, type GridColumnLayout, type RenderedColumn } from "@/registry/default/components/data-grid/data-grid-sdk";
import { cn } from "@/lib/utils";
import { DataGridPinnedRow } from "./pinned-row";
import type { ServerAggregateStatus } from "./use-data-grid-server-aggregate";

/** Props for {@link DataGridPinnedRowBand}. */
export type DataGridPinnedRowBandProps = {
  position: "top" | "bottom";
  rows: readonly unknown[];
  renderedColumns: readonly RenderedColumn[];
  layout: GridColumnLayout;
  rowHeight: number;
  template: string;
  /** The sticky header track's own height (not including this or any pinned band) — where the top band's `insetBlockStart` lands, directly under the header. */
  headerHeight: number;
  /**
   * `aria-rowindex` base for this band's rows (root's aria index layout: header rows, pinned-top
   * next, then data rows, pinned-bottom last). Top band: `1 + headerRowCount` (right after the header
   * rows, `2` without column groups), plus the rows of earlier top bands. Bottom band: after every
   * pinned-top and data row — root computes both bases and passes them through `RowBandRenderCtx`.
   */
  ariaRowIndexBase: number;
  /** Server value state: anything but `"ready"` dims the band; `"loading"` and `"stale"` set `aria-busy`. */
  status?: ServerAggregateStatus;
};

/**
 * A pinned-row sticky band: same layering as core's header layer — absolutely positioned inside
 * the sticky Viewport, counter-translated horizontally by the live scroll var so its cells track
 * the column canvas 1:1, but never moves vertically (rows canvas is the only vertically-scrolling
 * layer). The top band sits directly under the header; the bottom band sits flush with the
 * viewport's bottom edge (`insetBlockEnd: 0`) — both stay "in place" while data rows scroll
 * underneath, which is what core's frozen-edge shadow (root.tsx) keys off of.
 * `useDataGridPinnedRows`'s `rowBands.renderBand` calls this once per non-empty band.
 */
export function DataGridPinnedRowBand(props: DataGridPinnedRowBandProps): ReactNode {
  const { position, rows, renderedColumns, layout, rowHeight, template, headerHeight, ariaRowIndexBase, status = "ready" } = props;
  if (rows.length === 0) return null;

  const bandHeight = rows.length * rowHeight;
  const layerStyle: CSSProperties = {
    position: "absolute",
    insetInlineStart: 0,
    display: "grid",
    gridTemplateColumns: template,
    gridAutoRows: `${rowHeight}px`,
    height: bandHeight,
    // stacking context, same reasoning as header.tsx's own zIndex comment — must paint above the
    // rows canvas in DOM order regardless of scroll-driven transforms; below the header (zIndex 4).
    zIndex: GRID_LAYER.pinnedRowBand,
    // --grid-dir (-1 LTR, 1 RTL) signs the horizontal term, same as core's header/canvas layers:
    // the grid tracks mirror themselves under dir=rtl but transforms stay physical.
    transform: "translate3d(calc(var(--grid-dir, -1) * var(--grid-scroll-left, 0px)), 0, 0)",
    ...(position === "top" ? { insetBlockStart: headerHeight } : { insetBlockEnd: 0 }),
  };

  return (
    <div
      role="rowgroup"
      data-grid-pinned-row-band={position}
      data-status={status}
      aria-busy={status === "loading" || status === "stale" ? true : undefined}
      className={cn(status !== "ready" && "opacity-60", status === "loading" && "motion-safe:animate-pulse")}
      style={layerStyle}
    >
      {rows.map((row, i) => (
        <DataGridPinnedRow
          // oxlint-disable-next-line react/no-array-index-key -- a pinned row id can be a band id; band position is a stable key for a small consumer array.
          key={i}
          position={position}
          row={row}
          bandIndex={i}
          renderedColumns={renderedColumns}
          layout={layout}
          gridRowStart={i + 1}
          ariaRowIndex={ariaRowIndexBase + i}
          className={position === "bottom" ? "border-t border-border" : undefined}
        />
      ))}
    </div>
  );
}

"use client";

import { useLayoutEffect, useRef, type ReactNode } from "react";
import { useStore } from "zustand";
import { getCellValue, type AnyColumnDef } from "@/registry/default/components/data-grid/data-grid";
import { fullViewOf, isDev, useDataGridStoreApi, type DataGridReadState } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Built-in reducers skip `null` and `undefined` values; `sum`/`avg`/`min`/`max` give `undefined` when no value is left. A function receives every resolved value plus its source rows (empty values included — unlike the built-ins, a custom reducer owns its own empty handling). `TData` is the grid's row type: pass it at the hook call (or annotate `specs` as `AggregateSpecs<Row>`) so `rows` is typed. */
export type AggregateReducer<TData = unknown> = "sum" | "avg" | "min" | "max" | "count" | ((values: readonly unknown[], rows: readonly TData[]) => unknown);

/** One reducer per column id to aggregate. */
export type AggregateSpecs<TData = unknown> = Record<string, AggregateReducer<TData>>;

/** Options for {@link useDataGridAggregate}. */
export type UseDataGridAggregateOptions = {
  /** `"view"` (default) reduces over every row the sort and filter leave, all pages of a paged grid. `"page"` reduces over the shown page only. `"all"` reduces over the full `data` array, ignoring any active filter. */
  scope?: "view" | "page" | "all";
};

const NUMERIC_REDUCERS = new Set(["sum", "avg", "min", "max"]);

function reduceNumeric(reducer: "sum" | "avg" | "min" | "max", values: readonly number[]): number | undefined {
  if (values.length === 0) return undefined;
  switch (reducer) {
    case "sum":
      return values.reduce((a, b) => a + b, 0);
    case "avg":
      return values.reduce((a, b) => a + b, 0) / values.length;
    case "min":
      return values.reduce((a, b) => Math.min(a, b));
    case "max":
      return values.reduce((a, b) => Math.max(a, b));
  }
}

function aggregateColumn<TData>(reducer: AggregateReducer<TData>, column: AnyColumnDef, rows: readonly unknown[]): unknown {
  const values = rows.map((row) => getCellValue(row, column));
  // Boundary cast: the store keeps rows as unknown[], the user's reducer gets them typed.
  if (typeof reducer === "function") return reducer(values, rows as readonly TData[]);

  const nonEmpty = values.filter((v) => v !== null && v !== undefined);
  if (reducer === "count") return nonEmpty.length;
  if (NUMERIC_REDUCERS.has(reducer)) return reduceNumeric(reducer, nonEmpty as number[]);
  return undefined;
}

// Fires at most once per app, dev-only: a sparse (lazy) data array reached the reducer.
let warnedSparseData = false;

function warnSparseData(scope: "view" | "page" | "all", holes: number): void {
  if (!isDev() || warnedSparseData) return;
  warnedSparseData = true;
  console.warn(
    `[data-grid-pinned-rows] useDataGridAggregate (scope "${scope}") skipped ${holes} unloaded row(s): the data array is sparse (lazy loading), so the result covers loaded rows only. Use server-side totals or compute them outside the grid.`,
  );
}

// Fires at most once per app, dev-only: a spec key that matches no column id.
let warnedUnknownSpecKey = false;

function warnUnknownSpecKey(columnId: string): void {
  if (!isDev() || warnedUnknownSpecKey) return;
  warnedUnknownSpecKey = true;
  console.warn(
    `[data-grid-pinned-rows] useDataGridAggregate: spec key "${columnId}" matches no column id and is ignored (check for a typo)`,
  );
}

function computeAggregate<TData>(state: DataGridReadState, specs: AggregateSpecs<TData>, scope: "view" | "page" | "all"): Record<string, unknown> {
  const byId = new Map(state.columns.map((c) => [c.id, c] as const));
  const scoped = scope === "all" ? state.data : (scope === "page" ? state.viewIndex : fullViewOf(state.viewIndex)).map((i) => state.data[i]);
  // undefined rows are unloaded holes of a lazy grid; reduce over the loaded rows only.
  const rows = scoped.filter((row) => row !== undefined);
  if (rows.length !== scoped.length) warnSparseData(scope, scoped.length - rows.length);
  const result: Record<string, unknown> = {};
  for (const [columnId, reducer] of Object.entries(specs)) {
    const column = byId.get(columnId);
    if (!column) {
      warnUnknownSpecKey(columnId);
      continue;
    }
    result[columnId] = aggregateColumn(reducer, column, rows);
  }
  return result;
}

/**
 * Filter-aware aggregation for pinned totals/summary rows: reduces `specs` over the
 * grid's own state and returns a plain `{ [columnId]: value }` object — the same shape
 * `useDataGridPinnedRows`'s `topRows`/`bottomRows` expect, since pinned cells resolve values through
 * each column's `accessorKey`/`accessorFn` exactly like data rows. The object carries no row id, so
 * a pinned band gives it a band id when `getRowId` cannot resolve one. Values are resolved through
 * `getCellValue`, so `accessorFn` columns aggregate correctly, not just plain fields. Defaults to
 * `scope: "view"`, every row the sort and filter leave across all pages; `"page"` reduces over the
 * shown page only, and `"all"` over the raw `data`, ignoring the active filter. Recomputes only when `viewIndex`, `data`,
 * `scope`, or the `specs` object's own identity changes, so scrolling (no store write touches any of
 * those) never recomputes — same identity-guardrailed contract as the `plugins` prop; define
 * `specs` at module scope or memoize it, same discipline as any other grid callback prop.
 * `undefined` rows (unloaded holes of a lazy grid) are skipped and a dev warning fires once — on a
 * lazy grid the result covers loaded rows only. A spec key that matches no column id is ignored
 * and a dev warning fires once. `TData` types `rows` in custom reducers (see {@link AggregateReducer}).
 */
export function useDataGridAggregate<TData = unknown>(specs: AggregateSpecs<TData>, options: UseDataGridAggregateOptions = {}): Record<string, unknown> {
  const { scope = "view" } = options;
  const storeApi = useDataGridStoreApi();
  const cache = useRef<{ viewIndex: number[]; data: readonly unknown[]; scope: string; specs: AggregateSpecs<TData>; result: Record<string, unknown> } | null>(null);

  return useStore(storeApi, (state) => {
    const c = cache.current;
    if (c && c.viewIndex === state.viewIndex && c.data === state.data && c.scope === scope && c.specs === specs) {
      return c.result;
    }
    const result = computeAggregate(state, specs, scope);
    cache.current = { viewIndex: state.viewIndex, data: state.data, scope, specs, result };
    return result;
  });
}

/** Props for {@link DataGridAggregateReporter}. */
export type DataGridAggregateReporterProps<TData = unknown> = {
  specs: AggregateSpecs<TData>;
  options?: UseDataGridAggregateOptions;
  /** Called with the aggregated row whenever it changes — feed it into a `useState` that becomes a pinned band's `topRows`/`bottomRows` entry. */
  onChange: (row: Record<string, unknown>) => void;
};

/**
 * Bridges {@link useDataGridAggregate} out of the store. The pinned rows reach the grid as a
 * plugin's `rowBands` through the `plugins` prop — evaluated in the PARENT before the store exists — so a component that needs the live, filter-aware
 * aggregate to feed back into it must sit INSIDE the provider and report out. Render this as a plain
 * child anywhere under `<DataGridProvider>` (e.g. next to `<DataGridRoot>`) and hold its `onChange`
 * result in the parent's own state; that state is what you pass into `useDataGridPinnedRows`'s
 * `topRows`/`bottomRows`. A layout effect (not a passive one) reports the result before the browser paints,
 * so the parent's second render lands in the same frame as the first — no flash of an empty band.
 * Renders nothing.
 */
export function DataGridAggregateReporter<TData = unknown>(props: DataGridAggregateReporterProps<TData>): ReactNode {
  const { specs, options, onChange } = props;
  const row = useDataGridAggregate(specs, options);
  // Hold the latest callback in a ref and key the effect on `row` alone: an inline `onChange`
  // (fresh identity every parent render) would otherwise re-fire the effect on every render, and
  // a parent that stores the row with a spread (`{ ...prev, ...row }`) loops that forever.
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;
  useLayoutEffect(() => {
    onChangeRef.current(row);
  }, [row]);
  return null;
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { useStore } from "zustand";
import { serverSpecKey, type ServerSpec } from "@/registry/default/components/data-grid/data-grid";
import { isDev, useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Longest text a server value keeps; longer strings are cut. */
const MAX_SERVER_AGGREGATE_TEXT = 1000;

/** What `fetchAggregates` receives. */
export type FetchAggregatesRequest = {
  /** The sort, filters, and quick-search text the grid holds now. */
  spec: ServerSpec;
  /** The column ids whose values the band shows. */
  columnIds: readonly string[];
  /** Aborted when a newer request replaces this one, and on unmount. */
  signal: AbortSignal;
};

/** `"loading"`: no values yet. `"stale"`: old values stay while a newer request runs. `"error"`: the last request failed; old values stay. */
export type ServerAggregateStatus = "loading" | "stale" | "ready" | "error";

/** Options for {@link useDataGridServerAggregate}. */
export type UseDataGridServerAggregateOptions = {
  /** Resolves `{ [columnId]: value }` for the whole result of `spec`, not for the rows the grid holds. */
  fetchAggregates: (request: FetchAggregatesRequest) => Promise<Record<string, unknown>>;
  /** Columns to ask for. Default: every column. */
  columnIds?: readonly string[];
  /** Wait in ms before each request starts: on mount, after a filter, quick-search, or `columnIds` change, and after `refresh()` and `retry()`. `0` starts at once. Default `150`. */
  debounceMs?: number;
  /** Called once per failed request. */
  onError?: (error: unknown) => void;
};

/** Return value of {@link useDataGridServerAggregate}. */
export type ServerAggregateResult = {
  /** Sanitized values, ready for a pinned band's `topRows` or `bottomRows`. Identity changes only when a request lands. */
  row: Record<string, unknown>;
  status: ServerAggregateStatus;
  error: unknown;
  /** Requests the values again and keeps the old ones on screen until the answer lands. */
  refresh: () => void;
  /** True while the status is `"loading"` or `"stale"`. */
  loading: boolean;
  /** Requests again after a failure; does nothing without an error. */
  retry: () => void;
};

const EMPTY_ROW: Record<string, unknown> = {};

/** The result before the first request settles; start parent state from it. */
export const PENDING_SERVER_AGGREGATE: ServerAggregateResult = { row: EMPTY_ROW, status: "loading", error: null, loading: true, refresh: () => {}, retry: () => {} };

function aggregateKey(spec: ServerSpec): string {
  return serverSpecKey({ sorts: [], filters: spec.filters, searchText: spec.searchText });
}

function reportChange(onChange: (result: ServerAggregateResult) => void, result: ServerAggregateResult): void {
  try {
    onChange(result);
  } catch (error) {
    console.error("[data-grid-pinned-rows] onChange threw", error);
  }
}

function notifyError(onError: ((error: unknown) => void) | undefined, error: unknown): void {
  try {
    onError?.(error);
  } catch {
    // a throwing consumer callback must not break the grid
  }
}

function sanitizeAnswer(answer: unknown, columnIds: readonly string[], warnDropped: (columnId: string) => void): Record<string, unknown> {
  if (typeof answer !== "object" || answer === null || Array.isArray(answer)) {
    throw new TypeError("fetchAggregates must resolve an object of { [columnId]: value }");
  }
  const row: Record<string, unknown> = {};
  for (const id of columnIds) {
    if (!Object.prototype.hasOwnProperty.call(answer, id)) continue;
    const value = (answer as Record<string, unknown>)[id];
    if (typeof value === "string") row[id] = value.length > MAX_SERVER_AGGREGATE_TEXT ? value.slice(0, MAX_SERVER_AGGREGATE_TEXT) : value;
    else if (typeof value === "number" && Number.isFinite(value)) row[id] = value;
    else if (typeof value === "boolean" || value === null) row[id] = value;
    else warnDropped(id);
  }
  return row;
}

/**
 * Pinned-row values from a server. Calls `fetchAggregates` with the current spec on mount and again
 * after each filter, quick-search, or `columnIds` change (a sort never changes the aggregated rows), aborts the
 * request a newer one replaces, and drops its late answer. Pagination, scroll, and own-API grids
 * use it alike, because the request carries the spec and not the rows the grid holds. Answer
 * values are untrusted: unknown column ids are ignored, text is cut at 1000 characters,
 * and anything but text, finite numbers, booleans, and null is dropped.
 * Must run inside the grid provider; see {@link DataGridServerAggregateReporter}.
 */
export function useDataGridServerAggregate(options: UseDataGridServerAggregateOptions): ServerAggregateResult {
  const { debounceMs = 150 } = options;
  const storeApi = useDataGridStoreApi();
  const filters = useStore(storeApi, (s) => s.filterState);
  const sorts = useStore(storeApi, (s) => s.sortState);
  const searchText = useStore(storeApi, (s) => s.searchText);
  const columns = useStore(storeApi, (s) => s.columns);

  const spec = useMemo<ServerSpec>(() => ({ sorts, filters, searchText }), [sorts, filters, searchText]);
  const key = aggregateKey(spec);
  const columnIds = useMemo(() => options.columnIds ?? columns.map((c) => c.id), [options.columnIds, columns]);
  const columnKey = columnIds.join("\u0000");

  const latest = useRef({ options, spec, columnIds });
  useLayoutEffect(() => {
    latest.current = { options, spec, columnIds };
  });

  const [state, setState] = useState<{ row: Record<string, unknown>; status: ServerAggregateStatus; error: unknown }>({
    row: EMPTY_ROW,
    status: "loading",
    error: null,
  });
  const hasValues = useRef(false);
  const warned = useRef(false);
  const warnDropped = useCallback((id: string) => {
    if (!isDev() || warned.current) return;
    warned.current = true;
    console.warn(`[data-grid-pinned-rows] useDataGridServerAggregate dropped the value of column "${id}": only text, finite numbers, booleans, and null are shown.`);
  }, []);
  const statusRef = useRef<ServerAggregateStatus>("loading");
  const [tick, setTick] = useState(0);

  useEffect(() => {
    const controller = new AbortController();
    setState((prev) => (prev.status === (hasValues.current ? "stale" : "loading") ? prev : { ...prev, status: hasValues.current ? "stale" : "loading", error: null }));
    const start = () => {
      const { options: o, spec: s, columnIds: ids } = latest.current;
      void new Promise<unknown>((resolve) => resolve(o.fetchAggregates({ spec: s, columnIds: ids, signal: controller.signal })))
        .then((answer) => {
          if (controller.signal.aborted) return;
          const row = sanitizeAnswer(answer, ids, warnDropped);
          hasValues.current = true;
          setState({ row, status: "ready", error: null });
        })
        .catch((error: unknown) => {
          if (controller.signal.aborted) return;
          setState((prev) => ({ ...prev, status: "error", error }));
          notifyError(latest.current.options.onError, error);
        });
    };
    if (debounceMs <= 0) {
      start();
      return () => controller.abort();
    }
    const timer = setTimeout(start, debounceMs);
    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [key, columnKey, tick, debounceMs, warnDropped]);

  const refresh = useCallback(() => setTick((t) => t + 1), []);
  useLayoutEffect(() => {
    statusRef.current = state.status;
  });
  const retry = useCallback(() => {
    if (statusRef.current === "error") setTick((t) => t + 1);
  }, []);
  const loading = state.status === "loading" || state.status === "stale";

  return useMemo(() => ({ ...state, loading, refresh, retry }), [state, loading, refresh, retry]);
}

/** Props for {@link DataGridServerAggregateReporter}. */
export type DataGridServerAggregateReporterProps = UseDataGridServerAggregateOptions & {
  /** Called when the row, status, or error changes; hold the result in the parent's state and pass its `row` to a pinned band. */
  onChange: (result: ServerAggregateResult) => void;
};

/**
 * Bridges {@link useDataGridServerAggregate} out of the grid provider, like
 * `DataGridAggregateReporter`: render it as a child of the grid and keep the reported result in the
 * parent's state. Renders nothing.
 */
export function DataGridServerAggregateReporter(props: DataGridServerAggregateReporterProps): ReactNode {
  const { onChange, ...options } = props;
  const result = useDataGridServerAggregate(options);
  const onChangeRef = useRef(onChange);
  useLayoutEffect(() => {
    onChangeRef.current = onChange;
  });
  useLayoutEffect(() => {
    reportChange(onChangeRef.current, result);
  }, [result]);
  return null;
}
